          "rationales": {
            "type": "object",
            "additionalProperties": true,
            "description": "Short evidence-grounded reasons, keyed by rating field; do not include personal or confidential data."
          },
          "confidence": {
            "type": "object",
            "additionalProperties": false,
            "required": ["overall", "least_clear_field"],
            "properties": {
              "overall": { "type": "integer", "minimum": 1, "maximum": 5 },
              "least_clear_field": { "type": "string" }
            }
          }
        }
      }
    }
  }
}

:root {
  color-scheme: light;
  --ink: #142b2c;
  --muted: #526969;
  --paper: #f4f3ec;
  --card: #fffef9;
  --line: #cad5cd;
  --teal: #176b64;
  --teal-dark: #0f514c;
  --amber: #a6571b;
  --max: 1100px;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 17px/1.65 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
a { color: var(--teal-dark); text-underline-offset: 3px; }
a:hover { color: var(--amber); }
a:focus-visible { outline: 3px solid var(--amber); outline-offset: 4px; }
.skip { position: absolute; left: -9999px; top: 0; background: var(--card); padding: .6rem 1rem; }
.skip:focus { left: 1rem; z-index: 5; }
.wrap { width: min(var(--max), calc(100% - 2.5rem)); margin: 0 auto; }
header { border-bottom: 1px solid var(--line); }
.nav { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1.2rem 0; }
.brand { font-weight: 760; color: var(--ink); text-decoration: none; letter-spacing: -.02em; }
.brand span { color: var(--teal); }
nav ul { display: flex; gap: 1.3rem; list-style: none; margin: 0; padding: 0; font-size: .9rem; }
nav a { text-decoration: none; }
.hero { padding: 5.4rem 0 4.3rem; display: grid; grid-template-columns: 1.55fr .8fr; gap: 4rem; align-items: end; }
.eyebrow { color: var(--teal-dark); text-transform: uppercase; letter-spacing: .13em; font-size: .76rem; font-weight: 750; }
h1 { font-family: Georgia, serif; font-size: clamp(2.8rem, 6vw, 5.4rem); line-height: .99; font-weight: 500; letter-spacing: -.05em; margin: 1rem 0 1.5rem; max-width: 850px; }
.deck { font-size: 1.22rem; max-width: 730px; color: var(--muted); }
.note { border-left: 3px solid var(--amber); padding: .3rem 0 .3rem 1.2rem; font-size: .92rem; }
.note strong { display: block; margin-bottom: .5rem; }
.actions { display: flex; flex-wrap: wrap; gap: .8rem; margin-top: 1.8rem; }
.button { display: inline-block; border: 1px solid var(--teal-dark); padding: .65rem 1rem; text-decoration: none; font-weight: 650; font-size: .92rem; }
.button.primary { background: var(--teal-dark); color: white; }
.button.primary:hover { background: var(--ink); }
main section { padding: 3.4rem 0; border-top: 1px solid var(--line); }
h2 { font-family: Georgia, serif; font-size: clamp(2rem, 4vw, 3rem); font-weight: 500; line-height: 1.1; letter-spacing: -.03em; margin: 0 0 1.4rem; }
h3 { font-size: 1.04rem; line-height: 1.35; margin-top: 0; }
.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.card { background: var(--card); border: 1px solid var(--line); padding: 1.35rem; }
.card p:last-child { margin-bottom: 0; }
.label { font: 700 .72rem/1.4 ui-monospace, SFMono-Regular, Consolas, monospace; color: var(--teal-dark); text-transform: uppercase; letter-spacing: .07em; }
.split { display: grid; grid-template-columns: .9fr 1.5fr; gap: 4rem; }
.prose { max-width: 780px; }
.prose li { margin: .65rem 0; }
code { background: #e4ebe4; padding: .12em .35em; font-size: .88em; }
pre { background: var(--ink); color: #eaf4eb; padding: 1.2rem; overflow: auto; font-size: .82rem; line-height: 1.55; }
.status { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; margin-top: 1.5rem; }
.stat { border-top: 3px solid var(--teal); padding-top: .8rem; }
.stat strong { display: block; font: 500 1.8rem Georgia, serif; }
footer { border-top: 1px solid var(--line); padding: 2rem 0 3rem; color: var(--muted); font-size: .85rem; }
@media (max-width: 760px) {
  .hero, .split { grid-template-columns: 1fr; gap: 1.5rem; }
  .hero { padding-top: 3.5rem; }
  .grid { grid-template-columns: 1fr; }
  .status { grid-template-columns: repeat(2, 1fr); }
  nav ul { gap: .8rem; flex-wrap: wrap; justify-content: flex-end; }
  .brand { white-space: nowrap; }
}
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyon-threshold.pagewell.app/schema/incident-learning-record.schema.json",
  "title": "Incident Learning Record",
  "description": "Public-learning format for advanced-AI incidents and near misses. Design prototype v0.1; not an official regulatory form.",
  "type": "object",
  "additionalProperties": false,
  "required": ["spec_version", "record_id", "record_status", "synthetic", "public_summary", "incident", "timeline", "systems", "evidence", "assessment", "controls", "causal_analysis", "response", "corrective_actions", "redactions"],
  "properties": {
    "spec_version": { "const": "0.1.0" },
    "record_id": { "type": "string", "pattern": "^ILR-[0-9]{4}-[A-Za-z0-9][A-Za-z0-9_-]{2,63}$" },
    "based_on": { "type": ["string", "null"], "description": "Earlier record identifier for a correction or update; null for the first version." },
    "record_status": { "enum": ["preliminary", "updated", "final", "correction"] },
    "recorded_at": { "type": "string", "format": "date-time" },
    "synthetic": { "type": "boolean", "description": "True for fictional testing data. This flag alone does not establish provenance." },
    "public_summary": { "type": "string", "minLength": 40, "maxLength": 5000 },
    "incident": {
      "type": "object", "additionalProperties": false,
      "required": ["title", "event_class", "detection_context", "occurred_at", "discovered_at", "ongoing", "description"],
      "properties": {
        "title": { "type": "string", "minLength": 5, "maxLength": 200 },
        "event_class": { "enum": ["actual_incident", "near_miss", "control_signal", "undetermined"] },
        "detection_context": { "enum": ["deployment", "evaluation", "red_team", "monitoring", "third_party", "other", "unknown"] },
        "occurred_at": { "type": ["string", "null"], "format": "date-time" },
        "discovered_at": { "type": ["string", "null"], "format": "date-time" },
        "ongoing": { "type": ["boolean", "null"] },
        "description": { "type": "string", "minLength": 20 }
      }
    },
    "timeline": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["at", "event", "evidence_ids"],
        "properties": {
          "at": { "type": ["string", "null"], "format": "date-time", "description": "Null means timing unknown; do not invent precision." },
          "event": { "type": "string", "minLength": 3 },
          "evidence_ids": { "type": "array", "uniqueItems": true, "items": { "type": "string" } }
        }
      }
    },
    "systems": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["system_id", "description", "role", "model_version_public"],
        "properties": {
          "system_id": { "type": "string", "minLength": 1 },
          "description": { "type": "string", "minLength": 3 },
          "role": { "enum": ["model", "agent", "deployment", "tool", "control", "other", "unknown"] },
          "model_version_public": { "type": ["string", "null"] }
        }
      }
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["evidence_id", "kind", "summary", "source_class", "availability", "uri"],
        "properties": {
          "evidence_id": { "type": "string", "pattern": "^E[0-9A-Za-z_-]{1,32}$" },
          "kind": { "enum": ["observation", "log", "evaluation", "report", "external_statement", "estimate", "inference", "other"] },
          "summary": { "type": "string", "minLength": 3 },
          "source_class": { "enum": ["first_party", "independent", "third_party", "anonymous", "synthetic", "derived"] },
          "availability": { "enum": ["public", "available_on_request", "confidential", "destroyed", "unknown"] },
          "uri": { "type": ["string", "null"], "format": "uri" }
        }
      }
    },
    "assessment": {
      "type": "object", "additionalProperties": false,
      "required": ["actual_impact", "potential_impact", "preventive_control_performance", "preventive_control_rationale", "response_priority", "priority_rationale"],
      "properties": {
        "actual_impact": { "$ref": "#/$defs/impact" },
        "potential_impact": { "$ref": "#/$defs/impact" },
        "preventive_control_performance": { "$ref": "#/$defs/controlPerformance" },
        "preventive_control_rationale": { "type": "string", "minLength": 10 },
        "response_priority": { "enum": ["emergency", "urgent", "routine", "undetermined"] },
        "priority_rationale": { "type": "string", "minLength": 10 }
      }
    },
    "controls": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["control_id", "description", "layer", "performance", "rationale"],
        "properties": {
          "control_id": { "type": "string", "pattern": "^C[0-9A-Za-z_-]{1,32}$" },
          "description": { "type": "string", "minLength": 3 },
          "layer": { "enum": ["prevention", "detection", "response", "recovery", "governance", "other"] },
          "performance": { "$ref": "#/$defs/controlPerformance" },
          "rationale": { "type": "string", "minLength": 5 }
        }
      }
    },
    "causal_analysis": {
      "type": "object", "additionalProperties": false,
      "required": ["status", "contributing_factors", "alternative_explanations", "key_uncertainties", "evidence_that_would_change_assessment"],
      "properties": {
        "status": { "enum": ["preliminary", "stable", "disputed", "unknown"] },
        "contributing_factors": { "type": "array", "items": { "type": "string", "minLength": 3 } },
        "alternative_explanations": { "type": "array", "items": { "type": "string", "minLength": 3 } },
        "key_uncertainties": { "type": "array", "items": { "type": "string", "minLength": 3 } },
        "evidence_that_would_change_assessment": { "type": "string", "minLength": 10 }
      }
    },
    "response": {
      "type": "object", "additionalProperties": false,
      "required": ["immediate_actions", "ongoing_risk"],
      "properties": {
        "immediate_actions": { "type": "array", "items": { "type": "string", "minLength": 3 } },
        "ongoing_risk": { "type": "string", "minLength": 3 }
      }
    },
    "corrective_actions": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["action_id", "description", "owner_role", "status", "due_date", "verification"],
        "properties": {
          "action_id": { "type": "string", "pattern": "^A[0-9A-Za-z_-]{1,32}$" },
          "description": { "type": "string", "minLength": 5 },
          "owner_role": { "type": "string", "minLength": 2, "description": "Organizational role, not a person's name or contact details." },
          "status": { "enum": ["proposed", "in_progress", "completed", "verified", "ineffective", "abandoned"] },
          "due_date": { "type": ["string", "null"], "format": "date" },
          "verification": {
            "type": "object", "additionalProperties": false,
            "required": ["method", "result", "evidence_ids"],
            "properties": {
              "method": { "type": "string", "minLength": 5 },
              "result": { "type": ["string", "null"] },
              "evidence_ids": { "type": "array", "uniqueItems": true, "items": { "type": "string" } }
            }
          }
        }
      }
    },
    "redactions": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["field_path", "reason", "public_interest_note"],
        "properties": {
          "field_path": { "type": "string", "minLength": 1 },
          "reason": { "enum": ["personal_data", "security", "confidential_business", "legal", "other"] },
          "public_interest_note": { "type": "string", "minLength": 5 }
        }
      }
    },
    "extensions": {
      "type": "object", "description": "Namespaced jurisdiction- or community-specific additions; core meanings must not be changed.",
      "propertyNames": { "pattern": "^[a-z][a-z0-9_-]*\\.[a-z][a-z0-9_-]*$" },
      "additionalProperties": true
    }
  },
  "$defs": {
    "controlPerformance": { "enum": ["held", "degraded", "failed", "not_applicable", "unknown"] },
    "impact": {
      "type": "object", "additionalProperties": false,
      "required": ["severity", "scope", "reversibility", "affected_count_estimate", "rationale"],
      "properties": {
        "severity": { "enum": ["none_observed", "none_identified", "minor", "serious", "severe", "unknown"] },
        "scope": { "enum": ["individual", "limited_group", "widespread", "not_applicable", "unknown"] },
        "reversibility": { "enum": ["reversible", "partially_reversible", "irreversible", "not_applicable", "unknown"] },
        "affected_count_estimate": { "type": ["integer", "null"], "minimum": 0 },
        "rationale": { "type": "string", "minLength": 10 }
      }
    }
  }
}

